-- VarsityStay Phase 1: empty, real-data schema (NO demo rows).
-- Run in Supabase SQL Editor. Authentication identities live in auth.users.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role text not null default 'student' check(role in ('student','landlord','admin')), phone text, verified boolean not null default false, created_at timestamptz not null default now());
create table public.universities (id uuid primary key default gen_random_uuid(), name text not null unique, city text not null, province text, active boolean not null default true, created_at timestamptz not null default now());
create table public.properties (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id), university_id uuid not null references public.universities(id), title text not null, description text not null, address text not null, suburb text not null, city text not null, monthly_rent numeric(12,2) not null check(monthly_rent>=0), walk_minutes integer not null check(walk_minutes between 0 and 240), room_type text not null check(room_type in ('Single room','Shared room','Studio','Apartment','Bachelor','Ensuite')), available_rooms integer not null default 1 check(available_rooms>=0), contact_phone text not null, nsfas_friendly boolean not null default false, wifi boolean not null default false, security boolean not null default false, parking boolean not null default false, verified boolean not null default false, status text not null default 'pending' check(status in ('pending','published','rejected','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.property_images (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, url text not null, path text not null, created_at timestamptz not null default now());
create table public.reservations (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id), property_id uuid not null references public.properties(id), landlord_id uuid references public.profiles(id), request_type text not null check(request_type in ('room','viewing')), message text, status text not null default 'requested' check(status in ('requested','accepted','declined','cancelled','awaiting_payment','confirmed')), created_at timestamptz not null default now());
create table public.viewing_slots (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id), property_id uuid not null references public.properties(id) on delete cascade, start_at timestamptz not null, end_at timestamptz not null, created_at timestamptz not null default now(), check(end_at>start_at));
create table public.complaints (id uuid primary key default gen_random_uuid(), reporter_id uuid references public.profiles(id) on delete set null, category text not null check(category in ('maintenance','safety','payment','misrepresentation','landlord','other')), property_name text not null, area text not null, contact_email text not null, description text not null, status text not null default 'new' check(status in ('new','reviewing','resolved','closed')), created_at timestamptz not null default now());
create table public.student_reviews (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), property_name text not null, area text not null, university_id uuid references public.universities(id), rating integer not null check(rating between 1 and 5), sentiment text not null check(sentiment in ('recommended','warning')), body text not null, anonymous boolean not null default true, manager_contact text, status text not null default 'pending' check(status in ('pending','published','rejected')), created_at timestamptz not null default now());
create table public.advertisements (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id), headline text not null, description text, image_url text, starts_on date not null, ends_on date not null, priority integer not null default 0, status text not null default 'draft' check(status in ('draft','active','paused')), created_at timestamptz not null default now(), check(ends_on>=starts_on));
create table public.payment_transactions (id uuid primary key default gen_random_uuid(), reservation_id uuid not null references public.reservations(id), provider text not null, provider_reference text unique, amount_cents bigint not null check(amount_cents>=0), currency text not null default 'ZAR', status text not null default 'pending' check(status in ('pending','successful','failed','refunded')), verified_at timestamptz, created_at timestamptz not null default now());
create index properties_search on public.properties(status,university_id,monthly_rent); create index properties_owner on public.properties(owner_id); create index reservations_student on public.reservations(student_id); create index reservations_landlord on public.reservations(landlord_id); create index reviews_status on public.student_reviews(status); create index ads_dates on public.advertisements(starts_on,ends_on);
-- Do not trust a client-supplied role of admin.
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),case when new.raw_user_meta_data->>'role'='landlord' then 'landlord' else 'student' end);return new;end;$$;
create trigger after_auth_signup after insert on auth.users for each row execute function public.handle_new_user();
-- Populate owner on reservation server-side; the browser never controls it.
create function public.assign_reservation_landlord() returns trigger language plpgsql security definer set search_path='' as $$ begin select owner_id into new.landlord_id from public.properties where id=new.property_id and status='published' and available_rooms>0; if new.landlord_id is null then raise exception 'Property unavailable'; end if;return new;end;$$;
create trigger reservation_owner before insert on public.reservations for each row execute function public.assign_reservation_landlord();
-- Role helpers evaluate the authenticated user, not editable client fields.
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin'); $$;
create function public.is_landlord() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role='landlord'); $$;
-- RLS: all tables protected. Administrators are promoted manually by privileged database access.
alter table public.profiles enable row level security; alter table public.universities enable row level security; alter table public.properties enable row level security; alter table public.property_images enable row level security; alter table public.reservations enable row level security; alter table public.viewing_slots enable row level security; alter table public.complaints enable row level security; alter table public.student_reviews enable row level security; alter table public.advertisements enable row level security; alter table public.payment_transactions enable row level security;
create policy profiles_read on public.profiles for select using(id=(select auth.uid()) or public.is_admin());
create policy profiles_update on public.profiles for update using(id=(select auth.uid())) with check(id=(select auth.uid()));
-- Lock down role and verified columns: ordinary authenticated users may only update allowed fields.
revoke update on public.profiles from authenticated; grant update(full_name,phone) on public.profiles to authenticated;
create policy universities_read on public.universities for select using(active or public.is_admin());
create policy universities_admin on public.universities for all using(public.is_admin()) with check(public.is_admin());
create policy properties_read on public.properties for select using(status='published' or owner_id=(select auth.uid()) or public.is_admin());
create policy properties_insert on public.properties for insert to authenticated with check(owner_id=(select auth.uid()) and public.is_landlord() and status='pending' and verified=false);
-- Property changes must be mediated by an admin-controlled server function until field-level restrictions are implemented.
-- No direct UPDATE/DELETE policy: listings are submitted, then reviewed by staff.
create policy images_read on public.property_images for select using(exists(select 1 from public.properties p where p.id=property_id and (p.status='published' or p.owner_id=(select auth.uid()) or public.is_admin())));
create policy images_insert on public.property_images for insert to authenticated with check(exists(select 1 from public.properties p where p.id=property_id and p.owner_id=(select auth.uid()) and p.status='pending'));
create policy reservations_read on public.reservations for select to authenticated using(student_id=(select auth.uid()) or landlord_id=(select auth.uid()) or public.is_admin());
create policy reservations_insert on public.reservations for insert to authenticated with check(student_id=(select auth.uid()) and exists(select 1 from public.profiles x where x.id=(select auth.uid()) and x.role='student') and status='requested');
create policy slots_read on public.viewing_slots for select using(exists(select 1 from public.properties p where p.id=property_id and (p.status='published' or p.owner_id=(select auth.uid()))) or public.is_admin());
create policy slots_insert on public.viewing_slots for insert to authenticated with check(owner_id=(select auth.uid()) and exists(select 1 from public.properties p where p.id=property_id and p.owner_id=(select auth.uid())));
create policy complaints_insert on public.complaints for insert to authenticated with check(status='new' and reporter_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='student'));
create policy complaints_read on public.complaints for select to authenticated using(reporter_id=(select auth.uid()) or public.is_admin());
create policy reviews_read on public.student_reviews for select using(status='published' or author_id=(select auth.uid()) or public.is_admin());
-- Public-facing reviewers must never see private manager contact; restrict direct public column reads.
revoke select on public.student_reviews from anon,authenticated;
grant select(id,author_id,property_name,area,university_id,rating,sentiment,body,anonymous,status,created_at) on public.student_reviews to anon,authenticated;
create policy reviews_insert on public.student_reviews for insert to authenticated with check(author_id=(select auth.uid()) and status='pending');
create policy ads_read on public.advertisements for select using(status='active' and starts_on<=current_date and ends_on>=current_date or public.is_admin());
create policy payments_read on public.payment_transactions for select to authenticated using(public.is_admin() or exists(select 1 from public.reservations r where r.id=reservation_id and r.student_id=(select auth.uid())));
-- Storage bucket: public only for approved image assets; images linked to pending listings are URL-accessible if known.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('property-images','property-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy property_image_upload on storage.objects for insert to authenticated with check(bucket_id='property-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
-- IMPORTANT: Before production, move pending images to private storage or serve them through an authorized signed-URL endpoint.
-- Staff workflow: manually add real universities and approve listings with privileged SQL or Supabase admin console.
-- Promote an administrator ONLY with SQL Editor/service backend:
-- update public.profiles set role='admin' where id='REAL-AUTH-USER-UUID';
-- Publish a reviewed listing ONLY with privileged SQL: update public.properties set status='published',verified=true where id='REVIEWED-LISTING-UUID';
